* { box-sizing: border-box; }
:root { color-scheme: light; --ink: #263238; --paper: #fff9e9; --mint: #b9e4c9; --coral: #ed795d; --gold: #f4c95d; }
body { margin: 0; min-height: 100vh; padding: 32px 16px; display: grid; place-items: center; background-color: #d9efd9; background-image: linear-gradient(45deg, rgba(255,255,255,.28) 25%, transparent 25%), linear-gradient(-45deg, rgba(255,255,255,.28) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, rgba(255,255,255,.28) 75%), linear-gradient(-45deg, transparent 75%, rgba(255,255,255,.28) 75%); background-size: 28px 28px; color: var(--ink); font-family: system-ui, sans-serif; font-size: 16px; }
.board { width: min(100%, 520px); padding: 32px; background: var(--paper); border: 4px solid var(--ink); box-shadow: 8px 8px 0 var(--ink); }
.board-header { text-align: center; padding-bottom: 24px; border-bottom: 2px dashed #b8b39f; }
.eyebrow, .board-footer { font-size: 14px; font-weight: 800; letter-spacing: .12em; }
.eyebrow { color: #567b63; }
h1 { margin: 10px 0 4px; font-size: clamp(28px, 7vw, 38px); line-height: 1.15; }
.subtitle { margin: 0; color: #626d69; }
.alarm-form { display: grid; grid-template-columns: 1fr 1fr; gap: 18px 14px; padding: 24px 0; border-bottom: 2px dashed #b8b39f; }
.time-fields { display: flex; align-items: end; gap: 10px; }
.field { min-width: 0; display: grid; gap: 6px; }
.field label { font-weight: 700; }
.field label span { color: #68716d; font-weight: 400; }
.field input { width: 100%; min-height: 48px; padding: 10px 12px; border: 2px solid var(--ink); border-radius: 0; background: #fffdf6; color: var(--ink); font: inherit; }
.time-fields .field { flex: 1; }
.time-fields input { text-align: center; font-size: 20px; font-weight: 700; }
.time-colon { padding-bottom: 10px; font-size: 24px; font-weight: 800; }
.label-field { grid-column: 1 / -1; }
button { min-height: 48px; border: 2px solid var(--ink); border-radius: 0; color: var(--ink); font: inherit; font-weight: 800; cursor: pointer; transition: transform .08s ease, box-shadow .08s ease, background-color .15s ease; }
.add-button { grid-column: 1 / -1; background: var(--gold); box-shadow: 3px 3px 0 var(--ink); }
button:hover { filter: brightness(1.04); }
button:active { transform: translate(3px, 3px); box-shadow: none !important; }
button:focus-visible, input:focus-visible { outline: 3px solid #567b63; outline-offset: 3px; }
.alarms-section { padding-top: 24px; }
.list-heading { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
h2 { margin: 0; font-size: 21px; }
.count { margin: 0; padding: 5px 9px; background: var(--mint); border: 2px solid var(--ink); font-size: 14px; font-weight: 900; }
.alarm-list { display: grid; gap: 10px; margin: 16px 0 0; padding: 0; list-style: none; }
.alarm-item { display: grid; grid-template-columns: 1fr auto auto; align-items: center; gap: 10px; padding: 12px; border: 2px solid var(--ink); background: #fffdf6; box-shadow: 3px 3px 0 #b8b39f; }
.alarm-item.is-off { opacity: .62; background: #f1eee3; }
.alarm-info { min-width: 0; }
.alarm-time { display: block; font-size: 24px; font-weight: 850; font-variant-numeric: tabular-nums; line-height: 1.1; }
.alarm-label { display: block; overflow-wrap: anywhere; margin-top: 3px; color: #626d69; }
.toggle-button { min-width: 64px; padding: 7px; background: var(--mint); }
.is-off .toggle-button { background: #e5e0d2; }
.delete-button { min-width: 44px; padding: 7px; background: #ffe0d6; font-size: 20px; }
.empty-state { margin: 20px 0 4px; color: #626d69; text-align: center; }
.board-footer { display: flex; justify-content: center; gap: 9px; margin-top: 28px; color: #567b63; text-align: center; font-size: 12px; }
@media (max-width: 420px) { body { padding: 18px 12px; } .board { padding: 22px 18px; box-shadow: 5px 5px 0 var(--ink); } .alarm-form { grid-template-columns: 1fr; gap: 14px; } .time-fields, .label-field, .add-button { grid-column: 1; } .alarm-item { gap: 7px; padding: 10px 8px; } .toggle-button { min-width: 56px; } }

const form = document.querySelector('#alarm-form');
const hourInput = document.querySelector('#hour');
const minuteInput = document.querySelector('#minute');
const labelInput = document.querySelector('#label');
const list = document.querySelector('#alarm-list');
const count = document.querySelector('#enabled-count');
const emptyState = document.querySelector('#empty-state');

let alarms = [];
let nextId = 1;

function render() {
  const sorted = [...alarms].sort((a, b) => a.hour * 60 + a.minute - (b.hour * 60 + b.minute));
  list.replaceChildren();

  for (const alarm of sorted) {
    const item = document.createElement('li');
    item.className = `alarm-item${alarm.enabled ? '' : ' is-off'}`;
    const info = document.createElement('div');
    info.className = 'alarm-info';
    const time = document.createElement('span');
    time.className = 'alarm-time';
    time.textContent = `${String(alarm.hour).padStart(2, '0')}:${String(alarm.minute).padStart(2, '0')}`;
    info.append(time);
    if (alarm.label) {
      const label = document.createElement('span');
      label.className = 'alarm-label';
      label.textContent = alarm.label;
      info.append(label);
    }

    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.className = 'toggle-button';
    toggle.textContent = alarm.enabled ? 'ON' : 'OFF';
    toggle.setAttribute('aria-label', `${alarm.enabled ? 'Turn off' : 'Turn on'} alarm at ${time.textContent}${alarm.label ? `, ${alarm.label}` : ''}`);
    toggle.setAttribute('aria-pressed', String(alarm.enabled));
    toggle.addEventListener('click', () => {
      alarm.enabled = !alarm.enabled;
      render();
    });

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-button';
    remove.textContent = '×';
    remove.setAttribute('aria-label', `Delete alarm at ${time.textContent}${alarm.label ? `, ${alarm.label}` : ''}`);
    remove.addEventListener('click', () => {
      alarms = alarms.filter(entry => entry.id !== alarm.id);
      render();
    });

    item.append(info, toggle, remove);
    list.append(item);
  }

  count.textContent = `${alarms.filter(alarm => alarm.enabled).length} ON`;
  emptyState.hidden = alarms.length > 0;
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const hour = Number(hourInput.value);
  const minute = Number(minuteInput.value);
  if (!Number.isInteger(hour) || hour < 0 || hour > 23) {
    hourInput.setCustomValidity('Enter an hour from 0 to 23.');
    hourInput.reportValidity();
    return;
  }
  hourInput.setCustomValidity('');
  if (!Number.isInteger(minute) || minute < 0 || minute > 59) {
    minuteInput.setCustomValidity('Enter a minute from 0 to 59.');
    minuteInput.reportValidity();
    return;
  }
  minuteInput.setCustomValidity('');
  alarms.push({ id: nextId++, hour, minute, label: labelInput.value.trim(), enabled: true });
  form.reset();
  hourInput.focus();
  render();
});

hourInput.addEventListener('input', () => hourInput.setCustomValidity(''));
minuteInput.addEventListener('input', () => minuteInput.setCustomValidity(''));
render();
